public static SalesFormLetter construct(
    DocumentStatus _documentStatus,
    IdentifierName _className ,
    IdentifierName _methodName,
    SysOperationExecutionMode _executionMode )
{
    //Common common = this.parmSOurceTable();
    SalesFormLetter salesFormLetter;
    if (_documentStatus == DocumentStatus::None)
    {
        _documentStatus = DocumentStatus::Confirmation;
    }
    salesFormLetter = next construct(_documentStatus, _className, _methodName, _executionMode);
    _documentStatus = DocumentStatus::METCreditCheck;
    //contract.parmDocumentStatus(DocumentStatus::Confirmation);
    return salesFormLetter;
}
